#include "explorer.h"
#include <map>
#include <sstream>
#include <algorithm>
#include <random>
namespace mv {
std::string extendedInfo(const std::string& name){
 static const std::map<std::string,std::string> info={
{"SKULL","STRUCTURE: THE CRANIUM ENCLOSES THE BRAIN; FACIAL BONES FORM THE FRAMEWORK OF THE FACE. MOST SKULL JOINTS ARE IMMOVABLE SUTURES. THE MANDIBLE MOVES AT THE JAW JOINTS. CONNECTIONS: OPENINGS ALLOW NERVES AND BLOOD VESSELS TO PASS. THE SKULL ALSO SUPPORTS THE EYES AND THE NASAL AND ORAL CAVITIES."},
{"VERTEBRAL COLUMN","STRUCTURE: VERTEBRAE ARE GROUPED INTO CERVICAL, THORACIC AND LUMBAR REGIONS, FOLLOWED BY THE SACRUM AND COCCYX. DISCS BETWEEN MOST VERTEBRAL BODIES HELP ABSORB LOADS. CONNECTIONS: THE VERTEBRAL CANAL SURROUNDS THE SPINAL CORD. MUSCLES AND LIGAMENTS STABILISE THE SPINE WHILE PERMITTING CONTROLLED MOVEMENT."},
{"RIB CAGE","STRUCTURE: THE THORACIC CAGE INCLUDES RIBS, COSTAL CARTILAGES, STERNUM AND THORACIC VERTEBRAE. HUMANS TYPICALLY HAVE TWELVE PAIRS OF RIBS; THIS DRAWING SHOWS A REDUCED SET. CONNECTIONS: RIB MOVEMENTS AND THE DIAPHRAGM CHANGE CHEST VOLUME DURING BREATHING. THE CAGE ALSO PROVIDES ATTACHMENT SITES FOR TRUNK AND SHOULDER MUSCLES."},
{"PELVIS","STRUCTURE: TWO HIP BONES JOIN THE SACRUM TO FORM THE PELVIC RING. EACH HIP BONE DEVELOPS FROM THE ILIUM, ISCHIUM AND PUBIS. THE HIP SOCKETS ARTICULATE WITH THE FEMURS. CONNECTIONS: THE PELVIS LINKS THE SPINE WITH THE LOWER LIMBS. ITS SHAPE SUPPORTS WEIGHT TRANSFER AND PROVIDES ATTACHMENT FOR MUSCLES AND LIGAMENTS."},
{"ARM BONES","STRUCTURE: THE HUMERUS RUNS FROM SHOULDER TO ELBOW. THE RADIUS LIES ON THE THUMB SIDE OF THE FOREARM IN ANATOMICAL POSITION; THE ULNA LIES ON THE LITTLE-FINGER SIDE. CONNECTIONS: THE RADIUS ROTATES RELATIVE TO THE ULNA WHEN THE PALM TURNS. WRIST AND HAND BONES ADD FINE MOVEMENT; THEIR INDIVIDUAL BONES ARE NOT SHOWN HERE."},
{"LEG BONES","STRUCTURE: THE FEMUR CONNECTS THE HIP AND KNEE. THE PATELLA LIES IN THE QUADRICEPS TENDON. BELOW THE KNEE, THE TIBIA BEARS MOST OF THE LOAD AND THE FIBULA PROVIDES MUSCLE ATTACHMENT AND ANKLE SUPPORT. CONNECTIONS: JOINT SURFACES, CARTILAGE, LIGAMENTS AND MUSCLES WORK TOGETHER TO GUIDE MOVEMENT AND DISTRIBUTE FORCES."},
{"DELTOIDS","STRUCTURE: THIS TRIANGULAR SHOULDER MUSCLE HAS ANTERIOR, MIDDLE AND POSTERIOR PORTIONS. THEIR ACTIONS DIFFER: THE MIDDLE PORTION IS ESPECIALLY IMPORTANT IN LIFTING THE ARM AWAY FROM THE BODY. CONNECTIONS: IT WORKS WITH THE ROTATOR CUFF AND OTHER SHOULDER MUSCLES. THE VISIBLE FIBRE LINES ARE SCHEMATIC, NOT INDIVIDUAL MUSCLE CELLS."},
{"PECTORALS","STRUCTURE: PECTORALIS MAJOR FORMS MUCH OF THE FRONT CHEST MUSCLE. IT ATTACHES FROM THE CLAVICLE AND CHEST WALL TO THE HUMERUS. DIFFERENT PORTIONS CONTRIBUTE TO FLEXION, ADDUCTION AND MEDIAL ROTATION OF THE ARM. CONNECTIONS: PECTORALIS MINOR LIES DEEPER AND ACTS ON THE SCAPULA. THE MODEL DISPLAYS THE SUPERFICIAL CHEST MUSCLE REGION."},
{"BICEPS","STRUCTURE: BICEPS BRACHII HAS TWO PROXIMAL HEADS. IT CROSSES THE SHOULDER AND ELBOW AND ATTACHES DISTALLY TO THE RADIUS. ITS MAIN ACTIONS INCLUDE ELBOW FLEXION AND FOREARM SUPINATION. CONNECTIONS: IT WORKS WITH BRACHIALIS AND OTHER FLEXORS. TRICEPS BRACHII MAINLY EXTENDS THE ELBOW AND ACTS AS AN ANTAGONIST DURING FLEXION."},
{"ABDOMINAL MUSCLES","STRUCTURE: RECTUS ABDOMINIS IS SHOWN AS PAIRED SEGMENTS SEPARATED BY TENDINOUS INTERSECTIONS. THE OBLIQUE AND TRANSVERSE ABDOMINAL MUSCLES FORM OTHER LAYERS OF THE ABDOMINAL WALL. CONNECTIONS: TOGETHER THEY STABILISE THE TRUNK, HELP CONTROL INTRA-ABDOMINAL PRESSURE AND ASSIST FORCED EXPIRATION. THE VISIBLE SEGMENTS ARE NOT SEPARATE ORGANS."},
{"QUADRICEPS","STRUCTURE: THE GROUP COMPRISES RECTUS FEMORIS AND THREE VASTUS MUSCLES. THEY CONVERGE THROUGH THE QUADRICEPS TENDON AND PATELLA, CONTINUING THROUGH THE PATELLAR LIGAMENT TO THE TIBIA. CONNECTIONS: ALL EXTEND THE KNEE; RECTUS FEMORIS ALSO CROSSES THE HIP AND HELPS FLEX IT. THE MODEL GROUPS THE MUSCLES INTO A SIMPLIFIED THIGH REGION."},
{"TIBIALIS ANTERIOR","STRUCTURE: THIS MUSCLE RUNS ALONG THE FRONT OF THE LOWER LEG AND SENDS A TENDON ACROSS THE ANKLE TO THE MEDIAL FOOT. IT DORSIFLEXES AND INVERTS THE FOOT. CONNECTIONS: DURING WALKING IT HELPS CLEAR THE TOES AND CONTROLS LOWERING OF THE FOOT AFTER HEEL CONTACT. IT WORKS WITH OPPOSING CALF MUSCLES TO POSITION THE ANKLE."},
{"MOUTH","STRUCTURE: TEETH BREAK FOOD INTO SMALLER PIECES AND THE TONGUE MIXES IT WITH SALIVA. SALIVA LUBRICATES THE FOOD AND BEGINS STARCH DIGESTION. THE TONGUE SHAPES THE FOOD INTO A BOLUS. CONNECTIONS: THE TONGUE THEN MOVES THE BOLUS TOWARD THE PHARYNX. SWALLOWING BEGINS VOLUNTARILY BEFORE COORDINATED REFLEX ACTIONS CARRY THE FOOD ONWARD."},
{"OESOPHAGUS","STRUCTURE: THIS MUSCULAR TUBE LIES BEHIND THE TRACHEA AND PASSES THROUGH THE DIAPHRAGM. SEQUENTIAL MUSCLE CONTRACTIONS CALLED PERISTALSIS PROPEL A SWALLOWED BOLUS TOWARD THE STOMACH. CONNECTIONS: SPHINCTERS COORDINATE ENTRY AND EXIT; MUCUS REDUCES FRICTION. THE ANIMATION FOLLOWS A SIMPLIFIED FRONT-VIEW ROUTE AND DOES NOT SHOW THE AIRWAY-PROTECTION REFLEXES IN DETAIL."},
{"LIVER","STRUCTURE: LIVER CELLS PROCESS ABSORBED NUTRIENTS, STORE GLYCOGEN AND MAKE MANY PLASMA PROTEINS. THE LIVER ALSO PRODUCES BILE, WHICH ASSISTS FAT DIGESTION BY DISPERSING FAT INTO SMALLER DROPLETS. CONNECTIONS: BLOOD ARRIVING THROUGH THE HEPATIC PORTAL VEIN CARRIES MANY SUBSTANCES ABSORBED FROM THE DIGESTIVE TRACT. BILE TRAVELS THROUGH DUCTS TOWARD THE INTESTINE; FOOD DOES NOT PASS THROUGH THE LIVER."},
{"STOMACH","STRUCTURE: THE STOMACH HAS A MUSCULAR WALL AND AN EXPANDABLE LINING WITH FOLDS CALLED RUGAE. ACID AND ENZYMES HELP BEGIN PROTEIN DIGESTION WHILE CONTRACTIONS MIX FOOD INTO CHYME. CONNECTIONS: THE PYLORIC SPHINCTER REGULATES PASSAGE INTO THE DUODENUM. A MUCUS-BICARBONATE BARRIER HELPS PROTECT THE STOMACH LINING FROM ITS ACIDIC CONTENTS."},
{"PANCREAS","STRUCTURE: EXOCRINE PANCREATIC TISSUE RELEASES DIGESTIVE ENZYMES AND BICARBONATE INTO DUCTS LEADING TO THE DUODENUM. BICARBONATE HELPS NEUTRALISE ACIDIC CHYME. CONNECTIONS: ENDOCRINE ISLETS RELEASE HORMONES INTO THE BLOOD. INSULIN AND GLUCAGON HELP REGULATE BLOOD GLUCOSE. THE PANCREAS THEREFORE PARTICIPATES IN BOTH DIGESTION AND ENDOCRINE REGULATION."},
{"SMALL INTESTINE","STRUCTURE: THE DUODENUM, JEJUNUM AND ILEUM FORM THIS LONG COILED TUBE. FOLDS, VILLI AND MICROSCOPIC PROJECTIONS INCREASE THE ABSORPTIVE SURFACE. SEGMENTATION MIXES CONTENTS; PERISTALSIS MOVES THEM ONWARD. CONNECTIONS: MOST NUTRIENTS ENTER BLOOD CAPILLARIES OR INTESTINAL LYMPHATIC VESSELS AFTER ABSORPTION. THE COILS IN THIS MODEL ARE SCHEMATIC RATHER THAN A MEASURED INTESTINAL LENGTH."},
{"LARGE INTESTINE","STRUCTURE: THE CAECUM, COLON, RECTUM AND ANAL CANAL MAKE UP THE LARGE INTESTINE. ITS LINING ABSORBS REMAINING WATER AND ELECTROLYTES WHILE BACTERIA METABOLISE SOME RESIDUAL MATERIAL. CONNECTIONS: HAUSTRA GIVE THE COLON ITS POUCH-LIKE APPEARANCE. CONTENTS BECOME FAECES, WHICH ARE STORED BEFORE ELIMINATION. MOST NUTRIENT ABSORPTION HAS ALREADY OCCURRED IN THE SMALL INTESTINE."},
{"RIGHT LUNG","STRUCTURE: THE RIGHT LUNG IS DIVIDED INTO SUPERIOR, MIDDLE AND INFERIOR LOBES. BRONCHI DIVIDE REPEATEDLY INTO SMALLER AIRWAYS THAT LEAD TOWARD GAS-EXCHANGING ALVEOLI. CONNECTIONS: OXYGEN AND CARBON DIOXIDE DIFFUSE ACROSS THE THIN ALVEOLAR-CAPILLARY BARRIER. THE PLEURAL MEMBRANES REDUCE FRICTION AS THE LUNG MOVES WITH THE CHEST. BRANCHES AND LOBE LINES HERE ARE SIMPLIFIED."},
{"LEFT LUNG","STRUCTURE: THE LEFT LUNG HAS SUPERIOR AND INFERIOR LOBES. ITS MEDIAL BORDER INCLUDES A CARDIAC NOTCH, LEAVING ROOM FOR THE HEART. THE BRANCHING AIRWAY TREE DISTRIBUTES AIR WITHIN IT. CONNECTIONS: ALVEOLI EXCHANGE GASES WITH PULMONARY CAPILLARIES. ELASTIC RECOIL HELPS QUIET EXPIRATION WHEN INSPIRATORY MUSCLES RELAX. THIS ILLUSTRATION DOES NOT SHOW INDIVIDUAL ALVEOLI AT THEIR TRUE SCALE."},
{"TRACHEA","STRUCTURE: C-SHAPED CARTILAGE RINGS SUPPORT THE WINDPIPE. ITS INNER LINING CONTAINS MUCUS-PRODUCING CELLS AND CILIA THAT HELP MOVE TRAPPED MATERIAL TOWARD THE THROAT. CONNECTIONS: THE TRACHEA DIVIDES INTO THE MAIN BRONCHI. AIR TRAVELS THROUGH IT; A SWALLOWED FOOD BOLUS NORMALLY FOLLOWS THE OESOPHAGUS BEHIND IT."},
{"BRONCHI","STRUCTURE: THE MAIN BRONCHI ENTER THE LUNGS AND BRANCH INTO LOBAR AND SEGMENTAL BRONCHI, FOLLOWED BY SMALLER BRONCHIOLES. CARTILAGE SUPPORTS LARGER AIRWAYS; SMOOTH MUSCLE HELPS REGULATE AIRWAY CALIBRE. CONNECTIONS: THE CONDUCTING AIRWAYS DISTRIBUTE AIR. MOST GAS EXCHANGE OCCURS FARTHER ALONG IN THE ALVEOLI, NOT IN THE LARGE BRONCHI."},
{"DIAPHRAGM","STRUCTURE: THIS DOME-SHAPED SKELETAL MUSCLE SEPARATES THE THORAX FROM THE ABDOMEN. CONTRACTION FLATTENS AND LOWERS IT, INCREASING CHEST VOLUME AND HELPING DRAW AIR INTO THE LUNGS. CONNECTIONS: DURING QUIET EXPIRATION IT RELAXES AND ELASTIC RECOIL REDUCES LUNG VOLUME. OPENINGS TRANSMIT STRUCTURES SUCH AS THE OESOPHAGUS AND MAJOR VESSELS. MOVEMENT HERE IS EXAGGERATED FOR VISIBILITY."},
{"MAJOR ARTERIES","STRUCTURE: ARTERIES CARRY BLOOD AWAY FROM THE HEART UNDER PRESSURE. THEIR WALLS HAVE AN INNER LINING, A MIDDLE LAYER CONTAINING SMOOTH MUSCLE AND AN OUTER CONNECTIVE LAYER. CONNECTIONS: SYSTEMIC ARTERIES USUALLY CARRY OXYGEN-RICH BLOOD; PULMONARY ARTERIES CARRY OXYGEN-POOR BLOOD TO THE LUNGS. DIRECTION OF FLOW, RATHER THAN OXYGEN CONTENT, DEFINES AN ARTERY."},
{"MAJOR VEINS","STRUCTURE: VEINS RETURN BLOOD AT LOWER PRESSURE AND CAN HOLD A LARGE VOLUME OF BLOOD. MANY LIMB VEINS CONTAIN VALVES; MUSCLE CONTRACTION AND BREATHING HELP VENOUS RETURN. CONNECTIONS: PULMONARY VEINS CARRY OXYGEN-RICH BLOOD FROM THE LUNGS. BLUE IS A DRAWING CONVENTION ONLY. SMALL VEINS AND CAPILLARIES ARE OMITTED FROM THIS SCHEMATIC."},
{"HEART","STRUCTURE: FOUR CHAMBERS FORM TWO PUMPS: ATRIA RECEIVE BLOOD AND VENTRICLES EJECT IT. VALVES GUIDE ONE-WAY FLOW. THE MUSCULAR WALL IS CALLED THE MYOCARDIUM. CONNECTIONS: THE RIGHT VENTRICLE SUPPLIES THE LUNGS; THE LEFT SUPPLIES THE BODY THROUGH THE AORTA. CORONARY VESSELS NOURISH THE HEART MUSCLE. ITS ELECTRICAL CONDUCTION SYSTEM COORDINATES CONTRACTION."},
{"PERIPHERAL NERVES","STRUCTURE: NERVES CONTAIN BUNDLES OF AXONS OUTSIDE THE BRAIN AND SPINAL CORD. SENSORY PATHWAYS BRING INFORMATION TOWARD THE CENTRAL NERVOUS SYSTEM; MOTOR PATHWAYS CARRY COMMANDS TO EFFECTORS. CONNECTIONS: SOMATIC PATHWAYS ACT ON SKELETAL MUSCLES. AUTONOMIC PATHWAYS REGULATE FUNCTIONS OF ORGANS AND GLANDS. ONLY SELECTED ROUTES ARE SHOWN, NOT A COMPLETE MAP OF NAMED NERVES."},
{"SPINAL CORD","STRUCTURE: THE SPINAL CORD CONTAINS GREY MATTER INVOLVED IN PROCESSING AND WHITE-MATTER TRACTS THAT CARRY SIGNALS UP AND DOWN. SPINAL NERVES CONNECT IT TO THE BODY. CONNECTIONS: REFLEX CIRCUITS CAN PRODUCE RAPID RESPONSES WITHOUT WAITING FOR CONSCIOUS DECISIONS. VERTEBRAE, MENINGES AND CEREBROSPINAL FLUID PROVIDE PROTECTION; THE MODEL SIMPLIFIES ITS LOWER TERMINATION."},
{"BRAIN","STRUCTURE: THE CEREBRUM SUPPORTS PERCEPTION, VOLUNTARY ACTION AND HIGHER COGNITIVE FUNCTIONS. THE CEREBELLUM HELPS COORDINATE MOVEMENT AND BALANCE; THE BRAINSTEM SUPPORTS MANY ESSENTIAL AUTOMATIC FUNCTIONS. CONNECTIONS: FOLDS INCREASE THE SURFACE AREA OF THE CEREBRAL CORTEX. THE DRAWING SHOWS BROAD REGIONS ONLY, WITH DECORATIVE FOLD LINES RATHER THAN A MAP OF CORTICAL AREAS."},
{"RIGHT KIDNEY","STRUCTURE: NEPHRONS FILTER PLASMA, RECLAIM USEFUL WATER AND SOLUTES, AND SECRETE SELECTED SUBSTANCES INTO TUBULAR FLUID. THE REMAINING FLUID BECOMES URINE. CONNECTIONS: THE KIDNEY ALSO CONTRIBUTES TO BLOOD-PRESSURE CONTROL, RED-CELL PRODUCTION THROUGH ERYTHROPOIETIN AND ACTIVATION OF VITAMIN D. THE RIGHT KIDNEY USUALLY LIES SLIGHTLY LOWER BECAUSE OF THE LIVER."},
{"LEFT KIDNEY","STRUCTURE: THE CORTEX AND MEDULLA CONTAIN STRUCTURES THAT FORM AND CONCENTRATE URINE. URINE DRAINS THROUGH COLLECTING DUCTS, CALYCES AND THE RENAL PELVIS INTO THE URETER. CONNECTIONS: THE KIDNEYS HELP KEEP WATER, ELECTROLYTES AND ACID-BASE BALANCE WITHIN USEFUL LIMITS. MOST FILTERED WATER AND MANY USEFUL SUBSTANCES ARE RETURNED TO THE BLOOD RATHER THAN LOST IN URINE."},
{"URETERS","STRUCTURE: EACH URETER HAS A MUSCULAR WALL THAT PROPELS URINE BY PERISTALSIS. IT ENTERS THE BLADDER AT AN OBLIQUE ANGLE, WHICH HELPS LIMIT BACKFLOW DURING BLADDER FILLING AND CONTRACTION. CONNECTIONS: URINE MOVEMENT IS NOT SIMPLY A GRAVITY-FED FLOW. THE URETERS TRANSPORT URINE; THEY DO NOT PERFORM THE FILTRATION CARRIED OUT BY THE KIDNEYS."},
{"BLADDER","STRUCTURE: THE BLADDER HAS A DISTENSIBLE LINING AND A SMOOTH-MUSCLE WALL CALLED THE DETRUSOR. IT EXPANDS DURING FILLING WHILE OUTLET CONTROL HELPS RETAIN URINE. CONNECTIONS: DURING URINATION, COORDINATED NERVE SIGNALS CONTRACT THE DETRUSOR AND RELAX OUTLET RESISTANCE. STRETCH SIGNALS HELP COMMUNICATE BLADDER FULLNESS TO THE NERVOUS SYSTEM."},
{"URETHRA","STRUCTURE: THE URETHRA IS THE FINAL PASSAGE FROM THE BLADDER TO THE EXTERIOR. ITS COURSE AND LENGTH DIFFER BETWEEN TYPICAL MALE AND FEMALE ANATOMY. CONNECTIONS: SPHINCTER MECHANISMS CONTRIBUTE TO CONTINENCE. IN TYPICAL MALE ANATOMY IT ALSO CARRIES SEMEN AT A DIFFERENT TIME; IT SHOULD NOT BE CONFUSED WITH THE PAIRED URETERS."},
{"TESTES","STRUCTURE: SEMINIFEROUS TUBULES PRODUCE SPERM, WHILE INTERSTITIAL CELLS PRODUCE TESTOSTERONE. THE SCROTUM HELPS MAINTAIN A TEMPERATURE SUITABLE FOR SPERM PRODUCTION. CONNECTIONS: SPERM SUBSEQUENTLY MATURE IN THE EPIDIDYMIS, WHICH IS NOT SEPARATELY SELECTABLE HERE. HORMONAL SIGNALS FROM THE HYPOTHALAMUS AND PITUITARY REGULATE TESTICULAR ACTIVITY."},
{"DUCTUS DEFERENS","STRUCTURE: EACH DUCT CONTINUES FROM THE EPIDIDYMIS AND CARRIES SPERM TOWARD THE EJACULATORY DUCT. ITS MUSCULAR WALL CONTRACTS DURING EJACULATION. CONNECTIONS: IT TRANSPORTS SPERM RATHER THAN PRODUCING THEM. ACCESSORY GLANDS ADD MOST OF THE FLUID THAT COMBINES WITH SPERM TO FORM SEMEN."},
{"SEMINAL VESICLES","STRUCTURE: THESE PAIRED GLANDS CONTRIBUTE FLUID CONTAINING SUBSTANCES THAT SUPPORT SPERM, INCLUDING FRUCTOSE. THEIR DUCTS JOIN THE DUCTUS DEFERENS TO FORM THE EJACULATORY DUCTS. CONNECTIONS: THEY ARE NOT THE STORAGE SITE WHERE SPERM ARE MADE. THEIR CONTRIBUTION JOINS SECRETIONS FROM OTHER GLANDS IN FORMING SEMEN."},
{"PROSTATE","STRUCTURE: THE PROSTATE LIES BELOW THE BLADDER AROUND THE PROXIMAL URETHRA. ITS GLANDULAR TISSUE CONTRIBUTES SECRETIONS TO SEMINAL FLUID. CONNECTIONS: ITS POSITION LINKS IT CLOSELY TO BOTH REPRODUCTIVE AND URINARY ANATOMY. THIS SMALL SCHEMATIC DOES NOT DEPICT INTERNAL ZONES OR DUCTS."},
{"PENIS","STRUCTURE: THE PENIS CONTAINS ERECTILE TISSUE AND THE TERMINAL PORTION OF THE URETHRA. BLOOD FILLING ERECTILE SPACES PRODUCES CHANGES IN FIRMNESS. CONNECTIONS: THE URETHRA PROVIDES AN OUTLET FOR URINE OR SEMEN AT DIFFERENT TIMES. THE DRAWING IS AN EDUCATIONAL FRONT-VIEW SIMPLIFICATION, WITHOUT AN INTERNAL CROSS-SECTION."},
{"OVARIES","STRUCTURE: OOCYTES DEVELOP WITHIN FOLLICLES. OVARIAN HORMONES, INCLUDING OESTROGENS AND PROGESTERONE, PARTICIPATE IN REGULATION OF THE REPRODUCTIVE CYCLE. CONNECTIONS: OVULATION RELEASES AN OOCYTE NEAR THE UTERINE TUBE. THE OVARY PRODUCES GAMETES AND HORMONES; IT IS NOT THE USUAL SITE OF FERTILISATION OR IMPLANTATION."},
{"UTERINE TUBES","STRUCTURE: FIMBRIAE HELP GUIDE THE RELEASED OOCYTE INTO A UTERINE TUBE. CILIARY MOVEMENT AND MUSCULAR CONTRACTIONS ASSIST TRANSPORT TOWARD THE UTERUS. CONNECTIONS: FERTILISATION MOST COMMONLY OCCURS IN THE AMPULLA. THE TUBE COMMUNICATES WITH THE REGION NEAR THE OVARY RATHER THAN FORMING A SEALED DIRECT ATTACHMENT TO IT."},
{"UTERUS","STRUCTURE: THE MUSCULAR MYOMETRIUM SURROUNDS AN INNER LINING CALLED THE ENDOMETRIUM. HORMONAL CHANGES ALTER THAT LINING DURING THE REPRODUCTIVE CYCLE. CONNECTIONS: AN EMBRYO NORMALLY IMPLANTS IN THE ENDOMETRIUM. THE UTERINE WALL EXPANDS DURING PREGNANCY AND CONTRACTS DURING CHILDBIRTH. THE DRAWING SIMPLIFIES ITS CAVITY AND WALL THICKNESS."},
{"CERVIX AND VAGINA","STRUCTURE: THE CERVIX FORMS THE LOWER PORTION OF THE UTERUS AND CONTAINS A CANAL OPENING INTO THE VAGINA. THE VAGINA IS A MUSCULAR PASSAGE LEADING TO THE EXTERIOR. CONNECTIONS: CERVICAL MUCUS CHANGES DURING THE REPRODUCTIVE CYCLE. TOGETHER THESE STRUCTURES PROVIDE A PASSAGE FOR MENSTRUAL FLOW AND FORM PART OF THE BIRTH CANAL."},
};auto it=info.find(name);return it==info.end()?"":it->second;}
std::string systemInfo(int system,bool female){static const std::vector<std::string> info={
"OVERVIEW: BONES, JOINTS, CARTILAGE AND SUPPORTING CONNECTIVE TISSUES FORM THE BODY FRAMEWORK. THE AXIAL SKELETON INCLUDES THE SKULL, VERTEBRAL COLUMN AND THORACIC CAGE; THE APPENDICULAR SKELETON INCLUDES THE LIMBS AND THEIR GIRDLES. CONNECTIONS: BEYOND SUPPORT AND PROTECTION, BONE STORES MINERALS AND HOUSES MARROW INVOLVED IN BLOOD-CELL FORMATION. MUSCLES PULL ON BONES ACROSS JOINTS TO PRODUCE MOVEMENT. COMPARE WITH MUSCULAR TO SEE THAT RELATIONSHIP.",
"OVERVIEW: SKELETAL MUSCLES USE CHEMICAL ENERGY TO GENERATE FORCE. MUSCLE FIBRES ARE ORGANISED INTO BUNDLES; TENDONS TRANSMIT FORCE TO BONE. MOTOR NERVES COORDINATE WHEN THE FIBRES CONTRACT. CONNECTIONS: THIS LAYER SHOWS SELECTED SUPERFICIAL SKELETAL MUSCLE GROUPS. CARDIAC MUSCLE AND SMOOTH MUSCLE ARE DIFFERENT TISSUE TYPES. COMPARE WITH SKELETAL FOR ATTACHMENTS OR NERVOUS FOR CONTROL PATHWAYS.",
"OVERVIEW: THE DIGESTIVE TRACT TAKES IN FOOD, BREAKS IT DOWN, ABSORBS USABLE NUTRIENTS AND ELIMINATES UNDIGESTED RESIDUE. MECHANICAL ACTIONS AND CHEMICAL DIGESTION WORK TOGETHER. CONNECTIONS: ACCESSORY ORGANS SUCH AS THE LIVER AND PANCREAS SUPPLY SECRETIONS WITHOUT FOOD PASSING THROUGH THEM. NERVOUS AND HORMONAL SIGNALS COORDINATE DIGESTION. USE SWALLOW TO FOLLOW A BOLUS FROM MOUTH TO STOMACH; TIMING AND SCALE ARE ILLUSTRATIVE.",
"OVERVIEW: VENTILATION MOVES AIR INTO AND OUT OF THE LUNGS. GAS EXCHANGE TRANSFERS OXYGEN INTO BLOOD AND CARBON DIOXIDE OUT. THE AIRWAYS ALSO HELP CONDITION INHALED AIR. CONNECTIONS: THE DIAPHRAGM AND OTHER RESPIRATORY MUSCLES ALTER CHEST VOLUME. CIRCULATION CARRIES THE EXCHANGED GASES BETWEEN LUNGS AND TISSUES. COMPARE WITH CIRCULATORY; THIS MODEL SHOWS ONLY SELECTED AIRWAYS AND DOES NOT DEPICT ALVEOLI AT TRUE SCALE.",
"OVERVIEW: THE HEART, BLOOD AND BLOOD VESSELS FORM A TRANSPORT SYSTEM. PULMONARY CIRCULATION LINKS HEART AND LUNGS; SYSTEMIC CIRCULATION LINKS HEART AND OTHER TISSUES. CONNECTIONS: ARTERIES LEAD AWAY FROM THE HEART, VEINS RETURN BLOOD, AND CAPILLARIES PROVIDE EXCHANGE SURFACES. THIS LAYER OMITS CAPILLARY BEDS. COMPARE WITH RESPIRATORY FOR GAS EXCHANGE OR URINARY FOR FILTRATION OF CIRCULATING BLOOD.",
"OVERVIEW: THE BRAIN AND SPINAL CORD FORM THE CENTRAL NERVOUS SYSTEM. PERIPHERAL NERVES CONNECT THEM TO RECEPTORS, MUSCLES AND GLANDS. SENSORY INPUT, INTEGRATION AND MOTOR OUTPUT WORK TOGETHER. CONNECTIONS: NEURONS TRANSMIT SIGNALS, WHILE GLIAL CELLS SUPPORT THE NEURAL ENVIRONMENT. SOMATIC PATHWAYS CONTROL SKELETAL MUSCLE; AUTONOMIC PATHWAYS REGULATE MANY INTERNAL FUNCTIONS. COMPARE WITH MUSCULAR TO RELATE NERVE ROUTES TO MOVEMENT.",
"OVERVIEW: THE KIDNEYS FORM URINE AND REGULATE THE COMPOSITION OF BODY FLUIDS. URETERS TRANSPORT URINE, THE BLADDER STORES IT AND THE URETHRA PROVIDES THE FINAL OUTLET. CONNECTIONS: FILTRATION, REABSORPTION AND SECRETION WORK TOGETHER INSIDE NEPHRONS. THE URINARY SYSTEM HELPS REGULATE BLOOD VOLUME, ELECTROLYTES AND ACID-BASE BALANCE. COMPARE WITH CIRCULATORY TO CONNECT KIDNEY FUNCTION WITH THE BLOOD SUPPLY.",
"OVERVIEW: REPRODUCTIVE ORGANS PRODUCE GAMETES AND HORMONES AND SUPPORT THEIR TRANSPORT. TYPICAL MALE AND FEMALE STRUCTURES ARE PRESENTED AS SEPARATE SELECTABLE VIEWS. CONNECTIONS: THE SYSTEMS INTERACT WITH ENDOCRINE CONTROL. MALE STRUCTURES SUPPORT SPERM PRODUCTION AND DELIVERY; FEMALE STRUCTURES SUPPORT OOCYTE PRODUCTION AND, WHEN PREGNANCY OCCURS, IMPLANTATION AND DEVELOPMENT. PRESS F TO CHANGE THE ANATOMICAL VIEW.",
};if(system<0||system>=8)return "";return info[system]+(system==7?(female?" CURRENT VIEW: FEMALE.":" CURRENT VIEW: MALE."):"");}
std::vector<std::string> informationLines(const Explorer& e){
 std::string content;
 if(e.selected>=0&&e.selected<int(e.model().structures.size())){const auto& o=e.model().structures[e.selected];content="LOCATION: "+o.location+". ROLE: "+o.description+" "+extendedInfo(o.name);}
 else content=systemInfo(e.system,e.female);
 std::istringstream in(content);std::string word,line;std::vector<std::string> lines;
 while(in>>word){if(!line.empty()&&line.size()+word.size()+1>25){lines.push_back(line);line.clear();}if(!line.empty())line+=' ';line+=word;}
 if(!line.empty())lines.push_back(line);
 return lines;
}
int informationPages(const Explorer& e){return std::max(1,int((informationLines(e).size()+7)/8));}
void Explorer::turnPage(int direction){infoPage=std::max(0,std::min(informationPages(*this)-1,infoPage+direction));}
void Explorer::selectOrgan(int index){if(quiz)return;selected=index>=0&&index<int(model().structures.size())?index:-1;infoPage=0;}
void Explorer::toggleVariant(){if(quiz)return;if(system==7||(comparing&&secondary==7)){female=!female;selected=-1;infoPage=0;}}
void Explorer::toggleCompare(){if(quiz)exitQuiz();comparing=!comparing;if(secondary==system)nextSecondary();}
void Explorer::nextSecondary(){do{secondary=(secondary+1)%8;}while(secondary==system);}
void Explorer::swapSystems(){if(!comparing||quiz)return;std::swap(system,secondary);selected=-1;infoPage=0;resetAnimation();}
void Explorer::toggleAnimation(){if(quiz||(system!=2&&system!=3))return;if(system==2&&swallowTime>=8)swallowTime=0;playing=!playing;}
void Explorer::resetAnimation(){resetBreathing();swallowTime=0;}
bool Explorer::quizFinished() const{return quiz&&question>=int(questions.size());}
void Explorer::startQuiz(unsigned seed){
 std::mt19937 rng(seed);quiz=true;comparing=false;resetAnimation();questions.clear();question=score=0;answer=-1;infoPage=0;
 std::vector<std::pair<int,int>> targets;
 // Every round covers all eight systems, plus two additional distinct structures.
 for(int sys=0;sys<8;++sys){int n=int(models(female)[sys].structures.size());std::uniform_int_distribution<int> pick(0,n-1);targets.push_back({sys,pick(rng)});}
 std::vector<std::pair<int,int>> extra;for(int sys=0;sys<8;++sys)for(int i=0;i<int(models(female)[sys].structures.size());++i)if(std::find(targets.begin(),targets.end(),std::make_pair(sys,i))==targets.end())extra.push_back({sys,i});
 std::shuffle(extra.begin(),extra.end(),rng);targets.push_back(extra[0]);targets.push_back(extra[1]);std::shuffle(targets.begin(),targets.end(),rng);
 for(auto target:targets){const auto& m=models(female)[target.first];std::string correctName=m.structures[target.second].name;std::vector<std::string> distractors;
 for(const auto& o:m.structures)if(o.name!=correctName)distractors.push_back(o.name);
 if(distractors.size()<3)for(const auto& other:models(female))for(const auto& o:other.structures)if(o.name!=correctName&&std::find(distractors.begin(),distractors.end(),o.name)==distractors.end())distractors.push_back(o.name);
 std::shuffle(distractors.begin(),distractors.end(),rng);std::vector<std::string> options={correctName,distractors[0],distractors[1],distractors[2]};std::shuffle(options.begin(),options.end(),rng);
 questions.push_back({target.first,target.second,int(std::find(options.begin(),options.end(),correctName)-options.begin()),options});}
 loadQuestion();
}
void Explorer::loadQuestion(){if(quizFinished())return;const auto& q=questions[question];system=q.system;selected=q.structure;answer=-1;infoPage=0;resetAnimation();resetView();}
void Explorer::answerQuiz(int choice){if(!quiz||quizFinished()||answer!=-1||choice<0||choice>3)return;answer=choice;if(choice==questions[question].correct)++score;infoPage=0;}
void Explorer::nextQuestion(){if(!quiz||quizFinished()||answer<0)return;++question;infoPage=0;if(!quizFinished())loadQuestion();}
void Explorer::exitQuiz(){quiz=false;selected=-1;infoPage=0;resetAnimation();resetView();}
Point swallowPosition(double t){t=std::max(0.0,std::min(8.0,t));if(t<1)return {0,58};if(t<1.8)return {0,58+6*(t-1)/.8};if(t<6.8)return bezierPoint({0,64},{-4,110},{2,160},{13,196},(t-1.8)/5);return bezierPoint({13,196},{17,201},{24,207},{28,219},(t-6.8)/1.2);}
std::string swallowStage(double t){if(t<1)return "ORAL: FORMING A BOLUS";if(t<1.8)return "PHARYNGEAL: SWALLOWING";if(t<6.8)return "OESOPHAGEAL: PERISTALSIS";if(t<8)return "BOLUS ENTERS THE STOMACH";return "SWALLOW COMPLETE / PLAY TO REPEAT";}
}